node --input-type=module <<'JS'
import { loadVendorFile } from './tools/node-vendor.mjs';
for (const p of ['tape.js', 'typed-wasm.js', 'typed-rv32.js', 'typed-rv32-inline.js', 'typed-rv32-loops.js', 'typed-rv32-kernel.js']) {
  loadVendorFile('compiler/typed/' + p);
}
const source = \`
function put(out: buffer, x: i32): i32 { out.setCharCodeAt(0, x & 255); return 0; }
function probe(buf: buffer, out: buffer, n: i32): i32 {
  const frame = new Int32Array(4);
  for (let i = 0; i < 4; i = i + 1) {
    frame[i] = (buf.charCodeAt(i) << n) | (~buf.length >>> (32 - n));
  }
  put(out, frame[0]);
  return frame[1] + 0xbb67ae85;
}
\`;
const fns = [];
typedWasm.compileFunctions(source, 0, [], undefined, undefined, f => fns.push({
  name: f.name, params: f.params, frameBytes: f.arrayBytes
}));
const image = typedRv32.compile(source, [], undefined);
console.log(JSON.stringify({fns, entries: Object.keys(image.entries)}));
JS
